import json
import sys

try:
    with open(sys.argv[1], encoding="utf-8") as handle:
        value = json.load(handle)["design"]["num_cells"]
except (OSError, ValueError, KeyError):
    raise SystemExit(1)
if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
    print(value)
else:
    raise SystemExit(1)
